// === Tab: mySketch ===
let sliderHoehe
let baeume = []
let anzahlBaeume = 30 //ca. 30
let strahlen = []
let anzahlStrahlen = 20 //ca. 20
let horizontHoehe = 500 //ca. 200 - 500. Abstand unten bis Horizontlinie
let multiplikationVonYZuBreite = 4 //Vergrösserung der Bäume

function setup() {
	createCanvas(windowWidth, windowHeight);

	checkboxOptionen = createCheckbox();
	checkboxOptionen.position(10, 10);
	checkboxOptionen.checked(true);

	sliderHoehe = createSlider(100, 200);
	sliderHoehe.value(150) //150
	sliderHoehe.position(10, 30);
	sliderHoehe.size(100);

	sliderHorizontHoehe = createSlider(300, 700);
	sliderHorizontHoehe.value(500) //500
	sliderHorizontHoehe.position(10, 50);
	sliderHorizontHoehe.size(100);

	sliderTempo = createSlider(-100, 1000);
	sliderTempo.value(100) //100
	sliderTempo.position(10, 70);
	sliderTempo.size(100);

	sliderBlau = createSlider(0, 100);
	sliderBlau.value(50) //50
	sliderBlau.position(10, 90);
	sliderBlau.size(100);

	sliderVergroesserung = createSlider(0, 500);
	sliderVergroesserung.value(100) //50
	sliderVergroesserung.position(10, 110);
	sliderVergroesserung.size(100);


	// Bäume initialisieren
	for (let i = 0; i < anzahlBaeume; i++) {
		// Startpositionen zufällig verteilen
		let startX = random(-windowWidth, windowWidth * 2)
		let meanY = 35; // Mittelwert
		let sdY = 60; // Standardabweichung
		let startY = constrain(randomGaussian(meanY, sdY), 2, 200);
		baeume.push({
			x: startX,
			y: startY
		});
	}
	//sortieren
	baeume.sort((a, b) => a.y - b.y);

	// Strahlern initialisieren
	for (let i = 0; i < anzahlStrahlen; i++) {
		strahlen.push(windowWidth * 5 / anzahlStrahlen * i - windowWidth * 2)
	}
}

function draw() {
	backgroundZeichnen()
	optionenZeichnen()
	for (let i = 0; i < baeume.length; i++) {
		// Zeichnen
		baum(baeume[i].x, baeume[i].y)
		// Bewegung nach links
		baeume[i].x -= map(baeume[i].y, 0, 100, 1, 5) * sliderTempo.value() / 50;

		// Prüfen, ob das Rechteck links den Rand erreicht hat
		if (sliderTempo.value() > 0 && baeume[i].x < 0 - baeume[i].y * 2.1) {
			// Zurück an den rechten Rand und etwas zufällig verschieben
			baeume[i].x = windowWidth + baeume[i].y * 2.1 + random(200);
		} else if (sliderTempo.value() < 0 && baeume[i].x > windowWidth + baeume[i].y * 2.1) {
			baeume[i].x = 0 - baeume[i].y * 2.1 - random(200);
		}
	}
}


function optionenZeichnen() {
	if (checkboxOptionen.checked()) {
		sliderHoehe.style("display", "block")
		sliderHorizontHoehe.style("display", "block")
		sliderTempo.style("display", "block")
		sliderBlau.style("display", "block")
		sliderVergroesserung.style("display", "block")


		textAlign(LEFT, BOTTOM)
		fill("black")
		text("Höhe Baumelemente (" + sliderHoehe.value() + ")", 115, 50)
		text("Höhe Kamera (" + sliderHorizontHoehe.value() + ")", 115, 70)
		text("Geschwindigkeit (" + sliderTempo.value() + ")", 115, 90)
		text("Himmelsblau (" + sliderBlau.value() + ")", 115, 110)
		text("Grösse (" + sliderVergroesserung.value() + ")", 115, 130)



		textAlign(LEFT, TOP)
		text("Frame: " + frameCount + "\nFrames pro Sekunde: " + frameRate() + "\n",
			10, 150)

	} else {
		sliderHoehe.style("display", "none")
		sliderHorizontHoehe.style("display", "none")
		sliderTempo.style("display", "none")
		sliderBlau.style("display", "none")
		sliderVergroesserung.style("display", "none")

	}
}

function backgroundZeichnen() {
	background(220, 220, 250)
	horizontHoehe = sliderHorizontHoehe.value()
	noStroke()

	//Himmel zeichnen
	let tempHoeheHimmel = 1
	let yOffHimmel = 0
	for (let i = 0; i < 30; i++) {
		tempHoeheHimmel *= 1.3
		fill(165 + sliderBlau.value() - i * 5, 165 + sliderBlau.value() - i * 5, 255 - i * 1)
		rect(0, windowHeight - horizontHoehe + yOffHimmel, windowWidth, tempHoeheHimmel)
		yOffHimmel -= tempHoeheHimmel
	}

	//Strahlen zeichnen
	fill(255, 255, 200, 20)
	for (let i = 0; i < strahlen.length; i++) {
		triangle(
			windowWidth / 2, windowHeight - horizontHoehe + 15,
			0 + strahlen[i], 0,
			100 + strahlen[i], 0
		)
		strahlen[i] -= map(sliderTempo.value(), 0, 500, 0, 4)
		if (sliderTempo.value() > 0 && strahlen[i] < windowWidth * -2) {
			strahlen[i] = windowWidth * 3
		} else if (sliderTempo.value() < 0 && strahlen[i] > windowWidth * 3) {
			strahlen[i] = windowWidth * -2
		}
	}

	//Boden zeichnen
	let tempHoehe = 1
	let yOff = 0
	for (let i = 0; i < 30; i++) {
		tempHoehe *= 1.3
		fill(255 - i * 5, 215 - i * 5, 215 - i * 5)
		rect(0, windowHeight - horizontHoehe + yOff, windowWidth, tempHoehe)
		yOff += tempHoehe
	}
}

function baum(x, y) {
	noStroke()
	let farbanpassung = map(y, 0, 200, -20, 250)

	fill(200 - farbanpassung, 255 - farbanpassung, 200 - farbanpassung, 240)
	//rect(x, windowHeight - horizontHoehe + y, y, -y)
	let vergroesserung = y * multiplikationVonYZuBreite * sliderVergroesserung.value()/100

	let baseLineBaum = windowHeight - horizontHoehe + vergroesserung * 0.8 //OPTION Wie nahe am Boden ist die Kamer. 0.8

	var yOff = 0
	quad(
		x - vergroesserung / 2, baseLineBaum,
		x - vergroesserung / 5, baseLineBaum + (vergroesserung * 0.05),
		x + vergroesserung / 5, baseLineBaum + (vergroesserung * 0.05),
		x + vergroesserung / 2, baseLineBaum)
	for (let i = 0; i < 5; i++) {
		quad(
			x - vergroesserung / 2, baseLineBaum - yOff,
			x, baseLineBaum - yOff + (vergroesserung * 0.05),
			x + vergroesserung / 2, baseLineBaum - yOff,
			x, baseLineBaum - (vergroesserung * 0.75) - (i * y / 7) - yOff, //OPTION. Wie hoch sind die Dreiecke. 0.75
		)
		let vergroesserungMultiplikation = sliderHoehe.value()
		vergroesserung *= map(vergroesserungMultiplikation, 0, 255, 0, 1)
		yOff += vergroesserung * 0.8
	}

}

